queries.text:
UPDATE authors
SET bio = @bio
WHERE bio IS NOT NULL;

SELECT authors.id, authors.name, authors.bio, books.id, books.name, books.author_id, books.description
FROM authors JOIN books ON authors.id = books.author_id
ORDER BY authors.name;

SELECT authors1.id, authors1.name, authors1.bio, authors2.id, authors2.name, authors2.bio
FROM authors authors1 JOIN authors authors2 ON authors1.name = authors2.name
WHERE authors1.id < authors2.id;

SELECT authors.id, authors.name, authors.bio, books.id, books.name, books.author_id, books.description
FROM authors JOIN books ON authors.id = books.author_id
WHERE books.name = @name;
